-- EXEC.md EXEC-M143 solution 2 (user "also enable solusi 2", 2026-10-13): the tool contracts the code now offers.
-- check_references v2: an optional draft (the answer text with its references) is checked like the
-- answer without effect on the run: typed figures with the addresses equal to them and numbers
-- without a source are listed before the answer is sent.
-- Inactive like every market-ai-orc row; input schema and purpose from the code, every other column copied from the
-- previous version.
-- GENERATED by scripts/generate_tool_catalog_migration.py; market-ai-orc tests/test_data_need_tool.py fails on
-- drift. Do not edit by hand.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '1min';

DO $preflight$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE (tool_name, version) IN (('check_references', 'v1'))) <> 1 THEN
        RAISE EXCEPTION 'Expected the previous tool versions (''check_references'', ''v1'')';
    END IF;
    IF EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE (tool_name = 'check_references' AND version = 'v2')) THEN
        RAISE EXCEPTION 'The draft pre-check (solution 2) tool versions are already registered';
    END IF;
END
$preflight$;

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
    timeout_seconds, max_output_bytes, max_llm_result_rows,
    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
SELECT tool_name, tool_family, tool_type, next.purpose, next.input_schema::jsonb, output_schema,
       execution_type, handler_name, default_output_rows, max_output_rows,
       max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
       timeout_seconds, max_output_bytes, max_llm_result_rows,
       max_llm_result_bytes, max_llm_result_tokens,
       requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
       tool_specific_limits || '{"check_references":"at most 40 references and a draft of at most 30000 characters per call; this run''s references only; a draft check counts no refusal","design":"EXEC.md EXEC-M143 solution 2","registry_state":"registered from code (market-ai-orc) under the dev flags, inactive here"}'::jsonb, next.version, false
FROM public."Tool_Catalog" AS previous
JOIN (VALUES
    ('check_references', 'v1', 'v2', '{"additionalProperties":false,"properties":{"draft":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The answer text you are about to send, references unchanged, or null."},"references":{"description":"Value references, for example ''finding.a.estimates.primary.estimate|pp:2''.","items":{"type":"string"},"type":"array"}},"required":["references","draft"],"type":"object"}',
     'Shows what value references render to before you write the answer: give the addresses (with or without {{ }} and a format) and get each one''s displayed value, or why it does not resolve and the addresses that exist. Reads only this run''s results; no data is fetched or computed. With draft (the answer text you are about to send, its references unchanged) it also lists what the answer checks would refuse: figures typed without a reference, with the addresses that equal them, and numbers without a source. Pass the draft in the check you already make before answering; it does not count as a refusal.')
) AS next(name, from_version, version, input_schema, purpose)
  ON previous.tool_name = next.name AND previous.version = next.from_version;

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE NOT is_active AND ((tool_name = 'check_references' AND version = 'v2'))) <> 1 THEN
        RAISE EXCEPTION 'The draft pre-check (solution 2) tool versions were not registered';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'check_references' AND version = 'v2' AND input_schema::text LIKE '%draft%') THEN
        RAISE EXCEPTION 'The draft pre-check (solution 2) contracts are not in the registered rows';
    END IF;
END
$verify$;

COMMIT;
